const computeContainerProfiles:Record<string,{summary:string;concepts:string[];fit:string[];arch1:[string,string,string,string,string];arch2:[string,string,string,string,string];security:string[];optimization:string[];watch:string[];cost:string[];choices:{name:string;when:string}[];hook:string[]}>= {
  "App Service":{summary:"A managed Azure hosting platform for web apps, APIs and background workloads with built-in deployment, scaling and platform operations.",concepts:["An App Service app runs inside an App Service plan; the plan supplies compute, scale boundaries and pricing while the app supplies code and configuration.","Deployment slots, authentication, managed certificates, networking and autoscale are platform features with separate configuration and failure behavior.","The runtime stack, startup model, filesystem assumptions and outbound dependencies determine whether an app is portable and resilient."],fit:["Use it for HTTP applications and APIs when managed platform operations are more valuable than VM or container host control.","Use deployment slots for controlled promotion and keep state in external services so instances can scale or recycle.","Choose Container Apps or AKS when container-native scheduling, revisions or Kubernetes APIs are the primary requirement."],arch1:["Blue-green web deployment","A web app is promoted through a staging slot, then traffic is swapped after health checks while state remains external.","Azure App Service deployment slots pattern","App users","Front Door / WAF → App Service slots","Application / deployment / data / operations"],arch2:["Private API platform","A private API reaches protected data through VNet integration while identities and diagnostics remain explicit.","Azure App Service secure API architecture","API clients","API Management → private App Service","Identity / network / data / monitoring"],security:["Use managed identity, App Service authentication, private endpoints and access restrictions instead of embedding credentials in application settings.","Separate slot settings, deployment permissions and production secrets; validate that swaps do not move environment-specific secrets.","Protect outbound dependencies and logs because request payloads can contain customer data."],optimization:["Choose plan size and instance count from CPU, memory, latency and connection behavior; autoscale cannot correct blocking code.","Use slots, health checks, warm-up and externalized state to reduce deployment and restart impact.","Tune startup, connection pooling and caching before moving to a more operationally complex hosting model."],watch:["The plan is the scale and billing boundary; putting unrelated apps in one plan couples noisy-neighbor behavior.","Local filesystem writes are not a durable shared store and may disappear during recycle or scale-out.","A successful deployment does not prove slot-specific configuration or downstream connectivity."],cost:["App Service plan instances, deployment slots, storage, networking, certificates and connected services drive the bill.","Premium features and always-on capacity trade idle cost for startup and scaling behavior.","Include database, cache, gateway and monitoring costs in the request path."],choices:[{name:"App Service",when:"Managed HTTP web apps and APIs."},{name:"Container Apps",when:"Containerized apps with revisions and scale-to-zero."},{name:"Virtual Machines",when:"OS or runtime control is required."}],hook:["App Service plan = compute, app = workload, slot = release boundary.","Exam clue: managed web/API hosting with slots and platform authentication points to App Service."]},
  "Azure Compute Fleet":{summary:"A VM orchestration capability for provisioning and managing a mixed fleet of virtual machines across capacity, pricing and availability choices.",concepts:["A fleet expresses aggregate compute intent while individual VM sizes, zones, images and placement remain capacity decisions.","Spot and on-demand capacity can be combined, but eviction tolerance and workload interruption handling must be explicit.","Fleet-level orchestration is not a durable queue or application scheduler; workloads need their own health and work coordination."],fit:["Use it for large parallel VM workloads where capacity diversification and fleet-level placement matter.","Use idempotent workers and checkpointed jobs so capacity changes do not corrupt progress.","Choose VM Scale Sets for a homogeneous autoscaled service or Batch for job-oriented scheduling."],arch1:["Diversified batch fleet","A job coordinator submits checkpointed work to a diversified fleet and collects results in durable storage.","Azure Compute Fleet parallel workload pattern","Job submitter","Scheduler → Compute Fleet workers","Work queue / fleet / durable output / monitoring"],arch2:["Burst capacity with interruption","On-demand baseline and Spot capacity share a work pool; eviction-aware workers checkpoint before retry.","Azure Compute Fleet Spot capacity pattern","Workload controller","Queue → mixed VM fleet","Capacity / retry / state / governance"],security:["Use managed identity, network security groups, private access and least-privilege workload roles across the fleet.","Pin trusted images and patch baselines; fleet flexibility must not permit unapproved VM images.","Log placement, eviction, image and scale events for audit and incident analysis."],optimization:["Diversify sizes, zones and regions where the workload permits to improve capacity acquisition.","Match fleet allocation strategy to interruption tolerance and measure completion cost, not VM price alone.","Keep workers stateless and checkpoint frequently to reduce recovery time."],watch:["Capacity acquisition and Spot eviction are normal operating conditions, not exceptional application errors.","Mixed VM sizes can change throughput and memory behavior; benchmark the actual worker.","A fleet does not replace workload-level backpressure or result validation."],cost:["VM hours, Spot/on-demand mix, disks, networking, images, orchestration and monitoring contribute.","Retries and checkpoint storage can erase apparent Spot savings if the job is not interruption tolerant.","Compare cost per completed unit of work across fleet strategies."],choices:[{name:"Compute Fleet",when:"Large diversified VM capacity pools."},{name:"Virtual Machine Scale Sets",when:"Homogeneous service fleet autoscaling."},{name:"Batch",when:"Queued jobs with task scheduling."}],hook:["Compute Fleet optimizes VM capacity acquisition; the application still owns work correctness.","Exam clue: mixed VM sizes, capacity strategy and large parallel fleet point here."]},
  "Azure Quantum":{summary:"A managed Azure service for exploring quantum computing and optimization through workspaces, provider targets and hybrid classical workflows.",concepts:["A Quantum workspace organizes target access, jobs, storage and identity; the selected provider/backend determines execution characteristics.","Most practical workflows are hybrid: classical code prepares, submits and interprets quantum or optimization work.","Simulation, hardware queue time, qubit limits and algorithm quality are separate constraints."],fit:["Use it for quantum experimentation, optimization research and hybrid algorithms when a managed workspace and provider ecosystem are useful.","Keep classical preprocessing and result validation in conventional compute with reproducible experiment records.","Choose ordinary Batch or ML compute when the problem does not benefit from quantum or quantum-inspired execution."],arch1:["Hybrid optimization loop","A classical optimizer submits parameterized jobs, receives results and updates the next iteration.","Azure Quantum hybrid optimization pattern","Problem owner","Notebook / optimizer → Quantum workspace","Target / job queue / results / experiment log"],arch2:["Provider comparison","The same circuit is simulated, tested on alternative targets and compared using a common result schema.","Azure Quantum provider target workflow","Researcher","Workspace → provider targets","Simulation / hardware / analysis / governance"],security:["Restrict workspace, storage and target permissions; provider access and job data are part of the trust boundary.","Do not place proprietary algorithms or sensitive input data in shared notebooks or experiment logs.","Record provider, target, SDK and experiment versions for reproducibility."],optimization:["Use simulation and smaller circuits for development, then reserve hardware queue time for validated experiments.","Batch parameter sweeps and store compact result artifacts rather than retaining unnecessary raw output.","Compare algorithm quality and total classical overhead, not only quantum execution time."],watch:["Quantum hardware results are probabilistic and provider-dependent; a single run is not a production guarantee.","Workspace access does not remove provider queue, region or hardware availability constraints.","Optimization output still requires classical feasibility and business-rule validation."],cost:["Workspace operations, simulator or classical compute, provider execution, storage and notebook resources contribute.","Hardware shots, repeated experiments and hybrid optimizer iterations can dominate usage.","Estimate cost per validated solution, including failed experiments."],choices:[{name:"Azure Quantum",when:"Managed quantum and optimization experimentation."},{name:"Azure Batch",when:"Classical parallel job execution."},{name:"Azure Machine Learning",when:"Classical model training and experiment tracking."}],hook:["Azure Quantum connects workspaces to providers and hybrid jobs; it is not a general VM service.","Exam clue: quantum targets, circuits, workspaces and hybrid optimization point here."]},
  "Azure Spot Virtual Machines":{summary:"Discounted Azure VM capacity for interruptible workloads that can tolerate eviction and restart.",concepts:["Spot pricing exchanges lower cost for no guaranteed availability and possible eviction when Azure needs capacity.","Eviction policy, max price, checkpointing and retry behavior determine whether a workload is a good fit.","Spot VMs are compute instances, not a managed job queue; orchestration and durable work state belong elsewhere."],fit:["Use Spot VMs for batch rendering, simulations, CI workers and other restartable workloads.","Use checkpointed, idempotent workers behind a queue so eviction loses little progress.","Choose regular VMs or reserved capacity for stateful, latency-sensitive or non-interruptible services."],arch1:["Eviction-tolerant batch","A queue feeds workers that checkpoint results to storage and requeue interrupted tasks.","Azure Spot Virtual Machines batch pattern","Job source","Queue → Spot VM workers","Checkpoint / result / retry / telemetry"],arch2:["Spot CI runners","Build jobs run on ephemeral Spot runners while artifacts and logs remain in durable services.","Azure Spot Virtual Machines CI pattern","Developer","Pipeline → Spot runner","Image / build / artifact / governance"],security:["Use ephemeral identities, hardened images, network controls and least-privilege access to queues and artifacts.","Scrub secrets from images and clean disks before deallocation or reuse.","Log eviction and retry events without placing sensitive build or job payloads in diagnostics."],optimization:["Set realistic max price and use multiple sizes/zones where the workload allows.","Checkpoint before long operations and keep tasks small enough that eviction waste is limited.","Measure effective cost after retries, idle polling and recovery overhead."],watch:["Eviction can happen without application failure; design for interruption as a normal state transition.","Spot capacity availability changes by region, size and time; do not promise fixed capacity.","Never place the only copy of state on the VM."],cost:["Spot VM compute, disks, networking, queueing, checkpoints and retries contribute.","The discount is meaningful only when interruption waste stays low.","Compare total completed-work cost against standard VM or Batch alternatives."],choices:[{name:"Spot VMs",when:"Interruptible compute at discounted rates."},{name:"Virtual Machines",when:"Stable VM capacity is required."},{name:"Batch",when:"Managed task scheduling and retry are needed."}],hook:["Spot VMs are cheaper because Azure may evict them.","Exam clue: flexible, restartable workload plus interruption tolerance points to Spot VMs."]},
  "Azure Spring Apps":{summary:"A managed platform for deploying and operating Spring Boot applications with application lifecycle, service discovery and Java runtime integration.",concepts:["Applications, environments, service registry/configuration and managed infrastructure form separate operational boundaries.","Spring application behavior still depends on statelessness, externalized configuration and resilient downstream calls.","Build, runtime, network and observability settings must be promoted together across environments."],fit:["Use it when teams want managed Spring application hosting without operating the underlying Java platform.","Use external databases, caches and messaging so application instances can scale and restart safely.","Choose App Service for general web hosting or AKS when Kubernetes control and portability are primary."],arch1:["Spring microservices platform","Spring services register, call protected dependencies and expose health signals through a managed application environment.","Azure Spring Apps microservices pattern","Clients","Gateway → Spring Apps services","Config / registry / data / monitor"],arch2:["Progressive Spring release","A new Java build is deployed beside the current revision, tested through a controlled route and promoted after telemetry checks.","Azure Spring Apps release pattern","Delivery pipeline","Artifact → Spring Apps revision","Runtime / traffic / dependency / evidence"],security:["Use managed identity, private networking, TLS and centralized secret/configuration stores for application dependencies.","Restrict build and deployment roles separately from runtime identities.","Keep service-to-service authorization explicit; discovery is not authorization."],optimization:["Tune JVM memory, startup, connection pools and autoscaling from real request and GC telemetry.","Externalize state and use health probes so scale-out and rolling updates are safe.","Use build caching and progressive rollout to shorten delivery without hiding runtime regressions."],watch:["Spring Cloud concepts do not eliminate Azure resource limits, network failures or dependency timeouts.","Configuration drift between apps and environments can create failures that look like code defects.","A healthy JVM is not proof that downstream transactions are correct."],cost:["Managed application instances, build/runtime resources, networking, storage, logs and dependencies drive cost.","Always-on production capacity trades cost for predictable startup and latency.","Include database, cache, gateway and monitoring in service economics."],choices:[{name:"Azure Spring Apps",when:"Managed Spring Boot application platform."},{name:"App Service",when:"General managed web/API hosting."},{name:"AKS",when:"Kubernetes-native Java platform control."}],hook:["Spring Apps manages the Java/Spring platform boundary, not business data or service authorization.","Exam clue: managed Spring Boot lifecycle, discovery and configuration point here."]},
  "Azure VMware Solution":{summary:"A managed Azure service for running VMware workloads on dedicated Azure infrastructure with familiar vSphere-based operations.",concepts:["A private cloud contains VMware compute, storage and networking constructs; Azure connectivity and identity remain adjacent integration planes.","Migration, sizing, licensing, HCX mobility and disaster recovery are distinct workstreams.","The service reduces infrastructure procurement but does not remove VMware architecture and operational responsibility."],fit:["Use it to extend or migrate VMware estates when application compatibility and operational continuity outweigh cloud-native refactoring.","Connect the private cloud to Azure services deliberately through supported networking and identity patterns.","Choose native Azure VMs or PaaS when the workload can be modernized and VMware compatibility is not required."],arch1:["VMware estate extension","On-premises workloads migrate through HCX into an Azure VMware private cloud and consume Azure-connected services.","Azure VMware Solution hybrid architecture","Enterprise","On-prem VMware / HCX → Azure VMware Solution","Private cloud / Azure services / identity / operations"],arch2:["Disaster recovery landing zone","Replicated VMware workloads fail over to an Azure private cloud with tested network, DNS and application dependencies.","Azure VMware Solution disaster recovery pattern","Primary site","Replication → Azure VMware Solution","Recovery / network / runbook / monitoring"],security:["Use NSX-T segmentation, Azure network controls, identity federation and private connectivity; review both VMware and Azure permissions.","Protect vCenter, HCX, backup and replication credentials with separate administrative roles.","Audit migration and recovery operations because they can expose entire application estates."],optimization:["Size clusters from CPU, memory, storage I/O and failure-domain requirements, not VM count alone.","Right-size migrated VMs and use Azure-native services for new surrounding components where useful.","Test HCX throughput, recovery time and application dependencies before production cutover."],watch:["Private cloud capacity has cluster-level constraints and lead time; it is not elastic like a serverless platform.","VMware licensing, version compatibility and network dependencies can block migration.","A successful VM failover does not prove application-level recovery."],cost:["Dedicated host capacity, storage, networking, licensing, HCX, backup, replication and connected Azure services drive cost.","Idle reserved capacity is a material cost; consolidate and right-size after migration telemetry.","Include operational staffing and licensing in the total model."],choices:[{name:"Azure VMware Solution",when:"VMware compatibility and continuity are primary."},{name:"Azure Virtual Machines",when:"The workload can run natively on Azure VM infrastructure."},{name:"App Service/AKS",when:"Application modernization is the goal."}],hook:["AVS is a managed VMware private cloud on Azure, not a generic VM migration shortcut.","Exam clue: vSphere/NSX/HCX compatibility and Azure extension point to AVS."]},
  "Batch":{summary:"A managed Azure service for scheduling large-scale parallel and high-performance computing jobs across pools of compute nodes.",concepts:["Pools provide compute, jobs group work and tasks represent executable units; files, dependencies and outputs need explicit lifecycle handling.","Autoscale, task retry, scheduling constraints and low-priority/Spot capacity shape completion behavior.","Batch coordinates compute but durable input, output, checkpoints and application logic remain your responsibility."],fit:["Use it for independent or loosely coupled jobs such as rendering, simulation, media processing and scientific workloads.","Package tasks repeatably and write outputs to durable storage with deterministic naming.","Choose Functions for event-sized work or AKS for long-running container orchestration."],arch1:["Parallel media processing","Uploads create Batch tasks, workers process independent files and completed outputs are indexed for download.","Azure Batch parallel processing pattern","Uploader","Blob event → Batch job","Pool / tasks / output / monitor"],arch2:["Autoscaled scientific sweep","A parameter set is split into tasks, a pool scales to demand and result validation merges outputs.","Azure Batch parameter sweep pattern","Researcher","Dataset → Batch job","Compute pool / checkpoints / results / governance"],security:["Use managed identity, private storage access and least-privilege pool/task permissions.","Use trusted VM images and isolate untrusted task inputs from host management surfaces.","Control job submission and output access separately; job data may be sensitive."],optimization:["Choose task granularity, pool autoscale and VM mix from queue depth and startup overhead.","Use application packages, data locality and checkpointing to reduce repeated transfers and failed-task waste.","Monitor node allocation, task runtime and output throughput—not only CPU."],watch:["A completed task is not necessarily a validated business result; add checksums and domain validation.","Pool startup and image preparation can dominate short jobs.","Spot/low-priority capacity improves price only when retry behavior is sound."],cost:["Node hours, disks, storage transfers, pool startup, monitoring and retry work drive cost.","Idle pools and over-large nodes are common cost leaks.","Estimate cost per successful task including failed and requeued work."],choices:[{name:"Batch",when:"Managed queued parallel jobs."},{name:"Functions",when:"Short event-driven execution."},{name:"AKS",when:"Container orchestration and service workloads."}],hook:["Batch = pools, jobs and tasks for parallel work.","Exam clue: large queued compute jobs with task scheduling and autoscale point to Batch."]},
  "Cloud Services":{summary:"A legacy Azure hosted-service model for deploying roles with platform-managed virtual machines and application lifecycle operations.",concepts:["Cloud Services roles, packages, configurations and deployment slots define the application and upgrade boundary.","The platform manages role instances, but application state, role communication and external dependencies remain design concerns.","Classic and extended deployment models have different migration and feature expectations."],fit:["Use it primarily for existing role-based workloads where migration risk is higher than immediate modernization value.","Prefer App Service, VM Scale Sets, Container Apps or AKS for new applications unless role semantics are required.","Externalize state and treat role instances as replaceable during upgrades and faults."],arch1:["Role-based web and worker service","Web roles accept traffic while worker roles process messages and shared state remains in Azure data services.","Azure Cloud Services role architecture","Users","Load balancer → web roles","Worker roles / queue / storage / monitoring"],arch2:["Staged package deployment","A package is deployed to a staging slot, validated and swapped while role instances roll through upgrade domains.","Azure Cloud Services staged deployment","Release pipeline","Package → staging deployment","Upgrade domains / config / rollback / diagnostics"],security:["Harden role packages, certificates, remote access and deployment identities; legacy management surfaces require careful restriction.","Keep secrets out of packages and configuration artifacts where possible.","Apply network segmentation and monitor role instance health and administrative changes."],optimization:["Use upgrade domains and health checks to limit disruption; avoid oversized role instances with hidden coupling.","Move durable state and new supporting workloads to current managed services when practical.","Measure migration cost and operational risk before extending a legacy design."],watch:["Cloud Services is a legacy hosting model with migration implications; do not confuse it with App Service.","Role recycle and upgrade behavior can expose in-memory state assumptions.","Package/configuration drift makes incident reproduction difficult."],cost:["Role VM instances, storage, networking, diagnostics and connected services contribute.","Idle role capacity and legacy operational overhead can outweigh hosting price.","Include modernization and support costs in the decision."],choices:[{name:"Cloud Services",when:"Existing role-based hosted-service compatibility."},{name:"App Service",when:"Managed web/API modernization."},{name:"VM Scale Sets",when:"VM-level role control and current platform."}],hook:["Cloud Services uses web/worker roles and package-based deployment; it is not App Service.","Exam clue: legacy hosted roles, upgrade domains and deployment packages point here."]},
  "Linux Virtual Machines":{summary:"Azure IaaS virtual machines running Linux distributions with configurable compute, disks, networking and operating-system control.",concepts:["The VM is an IaaS boundary: Azure supplies infrastructure while the customer manages the guest OS, runtime, patching and application.","Managed disks, NICs, identities, extensions and availability constructs are separate resources with their own lifecycle.","Image, size, zone, disk and network choices determine performance and recovery behavior."],fit:["Use Linux VMs when OS control, custom agents, lift-and-shift compatibility or specialized software is required.","Use cloud-init/images and immutable deployment patterns to reduce configuration drift.","Choose App Service, Container Apps or AKS when platform-managed runtime operations are sufficient."],arch1:["Resilient Linux application","A load balancer distributes traffic across zonal VMs while data and secrets stay in managed services.","Azure Linux VM highly available application","Users","Load balancer → zonal Linux VMs","Managed disks / database / identity / monitor"],arch2:["Immutable Linux worker","A versioned image is rolled into a worker pool; queue state and outputs survive node replacement.","Azure Linux VM image-based worker","Queue","Work queue → Linux VM workers","Image / scale / storage / telemetry"],security:["Patch the guest OS, harden SSH, use Entra login or managed identity, and restrict network exposure.","Encrypt and protect disks, snapshots and backups; separate admin access from application identity.","Use Defender for Cloud, logging and just-in-time administration according to risk."],optimization:["Select VM size from CPU, memory, disk IOPS and network benchmarks; do not optimize on vCPU count alone.","Use images, autoscaling and reserved/savings options where utilization is stable.","Separate OS/data disks and tune caching/filesystems for the workload."],watch:["Azure resource health does not prove the guest OS or application is healthy.","Patching and extension failures are customer operational responsibilities.","A single VM or disk is not a high-availability design."],cost:["VM compute, disks, snapshots, IPs, bandwidth, monitoring, licenses and backups drive cost.","Stopped/deallocated and stopped-but-allocated states have different billing behavior.","Right-size from utilization and include operations in TCO."],choices:[{name:"Linux VMs",when:"Full Linux OS and runtime control."},{name:"App Service",when:"Managed web/API runtime."},{name:"Azure Container Instances",when:"Simple isolated container execution."}],hook:["Linux VM = Azure infrastructure plus customer-managed guest OS.","Exam clue: SSH, custom agents, OS packages and disk/network control point to Linux VMs."]},
  "SQL Server on Azure Virtual Machines":{summary:"SQL Server database software running on Azure VMs, combining IaaS control with Azure-managed integration and SQL workload options.",concepts:["The customer manages SQL Server, guest OS, patching, storage layout, backups and high availability configuration.","Azure VM size and disk throughput are as important as SQL configuration; data, log and tempdb paths have different I/O needs.","Licensing, HA/DR topology and maintenance windows are separate decisions."],fit:["Use it for SQL Server compatibility, instance-level features or migrations that do not fit a managed database service.","Use SQL-specific images and storage layouts, then automate patching, backup and health validation.","Choose Azure SQL Database or Managed Instance when reducing OS/engine administration is more important than instance control."],arch1:["SQL Server OLTP VM","An application reaches a zonal SQL VM pair with separated data/log storage and monitored backup paths.","SQL Server on Azure VM OLTP architecture","Application","Private app subnet → SQL VM","Data disks / log disks / backup / identity"],arch2:["SQL disaster recovery","Primary SQL Server replicates to a secondary region and a tested runbook changes application connection behavior.","SQL Server on Azure VM DR pattern","Primary region","SQL replication → secondary VM","Listener / backup / failover / monitoring"],security:["Use private networking, Entra/SQL authentication policy, Defender for SQL and least-privilege database roles.","Encrypt data and backups, protect keys and restrict sysadmin and VM administrator access.","Log database, OS and Azure control-plane changes with separate retention policies."],optimization:["Benchmark disk latency/IOPS, buffer memory, tempdb and query plans together; scaling VM CPU alone may not help.","Use reserved capacity and right-sized disks while preserving HA and backup objectives.","Automate index/statistics and maintenance within workload windows."],watch:["Azure VM health does not equal SQL availability; monitor engine, storage, listener and application paths.","A backup is not a tested restore or failover.","Licensing and HA design can dominate cost and complexity."],cost:["VM compute, SQL licensing, managed disks/IOPS, backup, networking, monitoring and DR replicas contribute.","Include passive/secondary capacity and storage in the cost model.","Compare full operational TCO against managed SQL offerings."],choices:[{name:"SQL on Azure VM",when:"SQL Server instance control and compatibility."},{name:"Azure SQL Managed Instance",when:"Managed SQL instance with reduced OS operations."},{name:"Azure SQL Database",when:"Database-level PaaS is sufficient."}],hook:["SQL on Azure VM preserves instance/OS control and customer operations.","Exam clue: SQL Server compatibility plus custom instance/OS control points here."]},
  "Static Web Apps":{summary:"A managed Azure hosting service for static front ends with integrated CI/CD, global delivery and optional serverless APIs.",concepts:["The static site, deployment workflow, preview environments and API backend are related but separate resources.","Build output is immutable per deployment while dynamic data and secrets belong in APIs or external services.","Routing, authentication and environment configuration determine how a static client reaches protected backends."],fit:["Use it for static or Jamstack front ends with Git-based deployment and lightweight serverless APIs.","Keep business rules and secrets server-side; use preview environments to validate pull requests safely.","Choose App Service or Container Apps when the server must own rendering or long-running processes."],arch1:["Static front end with API","A Git commit builds the front end, deploys an immutable site and calls a protected serverless API for data.","Azure Static Web Apps full-stack pattern","Browser","Static Web Apps → managed API","Auth / data / CI/CD / monitoring"],arch2:["Preview-to-production flow","A pull request creates an isolated preview, automated checks run, and the approved branch promotes to production.","Azure Static Web Apps preview environment","Developer","Pull request → preview environment","Build / review / promote / rollback"],security:["Use platform authentication, API authorization, secure headers and server-side validation; client routes are not a security boundary.","Store secrets in managed runtime configuration or Key Vault-backed APIs, never in static bundles.","Restrict repository/deployment tokens and review preview data isolation."],optimization:["Optimize static assets, cache headers and build output; keep dynamic calls narrow and cacheable where safe.","Use preview environments and atomic deployments to reduce release risk.","Move compute-heavy or stateful functions to a suitable backend rather than stretching the static platform."],watch:["A static deployment can be healthy while API calls, CORS or auth claims fail.","Preview environments can accidentally reach production data if backend isolation is weak.","Client-side configuration is visible to every visitor."],cost:["Static hosting, bandwidth, API execution, data services, custom domains and build/monitoring operations contribute.","Static delivery is inexpensive, but backend and data costs usually dominate dynamic workloads.","Estimate traffic, API calls and build frequency together."],choices:[{name:"Static Web Apps",when:"Static front end plus lightweight APIs and CI/CD."},{name:"App Service",when:"Server-rendered or full web application."},{name:"Container Apps",when:"Containerized web/API with revisions."}],hook:["Static Web Apps serves built front ends; dynamic business logic stays behind APIs.","Exam clue: Git-based static deployment, preview environments and managed API integration point here."]},
  "Virtual Machine Scale Sets":{summary:"An Azure resource for deploying and managing groups of load-balanced VMs with autoscale, upgrade and availability controls.",concepts:["A scale set defines a model for instances; instance health, upgrade policy, zones and autoscale determine fleet behavior.","Uniform and flexible orchestration support different placement and lifecycle needs.","Stateless service design, shared state and load-balancer health probes are required for safe scale-out."],fit:["Use it for horizontally scaled VM services, custom agents and fleets that need VM-level control.","Use images and rolling upgrades so instances are replaceable and consistent.","Choose App Service or Container Apps for managed application hosting with less guest OS responsibility."],arch1:["Zonal web fleet","A load balancer routes to zonal VM instances while autoscale responds to demand and health probes remove bad nodes.","Azure VM Scale Sets web tier","Users","Front Door / load balancer → VMSS","Autoscale / image / data / monitor"],arch2:["Rolling worker fleet","A new model version rolls through workers while queue depth drives instance count and durable state remains external.","Azure VM Scale Sets worker pattern","Queue","Work queue → VMSS workers","Upgrade / checkpoint / identity / telemetry"],security:["Use hardened images, managed identity, network security groups and just-in-time admin access.","Separate model/image publishing permissions from instance operations and workload identity.","Protect metadata, disks and autoscale actions from overly broad roles."],optimization:["Tune autoscale on queue depth or meaningful service metrics rather than CPU alone.","Use zones, rolling upgrades, health probes and instance repair for availability.","Right-size image, disk and network settings; eliminate configuration work at boot."],watch:["Autoscale changes instance count, not application correctness or database capacity.","Bad health probes can cause an outage by removing healthy nodes or retaining broken ones.","Model drift and manual instance changes undermine repeatability."],cost:["VM instances, disks, IP/load balancing, monitoring, images and outbound transfer drive cost.","Minimum instance count and overprovisioning protect availability but create baseline spend.","Compare operational cost with managed PaaS alternatives."],choices:[{name:"VM Scale Sets",when:"Autoscaled VM fleet with OS control."},{name:"App Service",when:"Managed web/API hosting."},{name:"AKS",when:"Container orchestration is the control plane."}],hook:["VMSS manages a repeatable VM fleet and its lifecycle.","Exam clue: autoscale, rolling upgrades, instance health and zones point to Scale Sets."]},
  "Virtual Machines":{summary:"Azure’s general-purpose IaaS compute service for running Windows or Linux workloads with control over guest operating system, disks and networking.",concepts:["A VM combines a selected image, size, disks, NICs and identity; each choice affects performance, security and recovery.","Availability sets, zones, scale sets and backup solve different resilience levels.","Azure manages the physical host, while the customer manages the guest OS and workload."],fit:["Use VMs for lift-and-shift, custom software, appliances and workloads needing OS-level control.","Automate image creation, patching, backup and recovery; avoid hand-configured snowflake servers.","Choose PaaS or containers when the workload does not need VM-specific control."],arch1:["Three-tier VM application","A protected web tier reaches an application tier and database tier with separate subnets, disks and monitoring.","Azure Virtual Machines three-tier architecture","Users","Load balancer → web/app VMs","Database / identity / backup / monitor"],arch2:["Lift-and-shift with recovery","A workload runs in a primary region with backup and replicated recovery capacity in a paired region.","Azure VM disaster recovery pattern","Primary workload","VMs → Recovery Services vault","Replica / runbook / DNS / evidence"],security:["Harden images, restrict management ports, use managed identity and apply network segmentation.","Encrypt disks and backups, control administrator roles and patch the guest OS continuously.","Use Defender for Cloud and central logging for host and application signals."],optimization:["Select size and disk tier from measured workload profiles; use reservations or savings plans for steady usage.","Use images, extensions and automation to reduce provisioning time and drift.","Separate data disks, tune caching and monitor memory/IO rather than only CPU."],watch:["A running VM is not automatically patched, backed up or highly available.","Stop/deallocate, disk, IP and licensing behavior affect both operations and cost.","A zone or availability set protects infrastructure failure modes, not bad application design."],cost:["VM compute, disks, IPs, bandwidth, backup, monitoring and software licenses drive cost.","Idle allocated VMs and premium disks are frequent avoidable charges.","Model availability and DR replicas as part of production cost."],choices:[{name:"Virtual Machines",when:"General IaaS and guest OS control."},{name:"App Service",when:"Managed HTTP application hosting."},{name:"Azure Batch",when:"Queued parallel jobs."}],hook:["Azure VMs provide infrastructure; the customer owns the guest OS and workload operations.","Exam clue: custom OS/software, disks and network control point to Virtual Machines."]},
  "Azure Virtual Desktop":{summary:"A managed Azure service for delivering Windows desktops and applications through pooled or personal session hosts.",concepts:["Host pools, application groups, workspaces and session hosts form separate delivery and management boundaries.","Pooled desktops optimize density while personal desktops preserve individual state; profile storage and identity are critical dependencies.","User experience depends on network path, graphics, profile I/O and session-host sizing."],fit:["Use it for secure remote desktops, task workers, contractors and Windows applications that are difficult to modernize.","Use pooled hosts for standardized task workloads and personal hosts for persistent user environments.","Choose Windows 365 when a simpler Cloud PC assignment model is preferred."],arch1:["Pooled task-worker desktops","Users authenticate through Entra ID, connect to a pooled host and store profiles in a resilient profile service.","Azure Virtual Desktop pooled host pool","Users","AVD client → host pool","Profile storage / apps / identity / monitor"],arch2:["Secure remote application delivery","A published application runs on session hosts with private access to business services and policy-controlled user identity.","Azure Virtual Desktop app group pattern","Employee","Workspace → RemoteApp","Session host / private app / profile / governance"],security:["Use Entra ID, Conditional Access, MFA, least privilege and network controls for users, hosts and management.","Protect profile containers and application data; session host access is not equivalent to data authorization.","Patch golden images and session hosts, and audit clipboard, drive and peripheral redirection."],optimization:["Right-size host pools from concurrency, profile I/O and application mix; autoscale around working hours.","Use pooled hosts and optimized images for density, while keeping user profile state external.","Measure sign-in, profile load, protocol latency and application performance."],watch:["Host pool health can look good while profile storage or line-of-business apps create poor user experience.","User data and session state require explicit recovery and privacy controls.","Graphics workloads need specialized sizing and licensing assumptions."],cost:["Session host compute, storage/profiles, networking, identity, apps, licensing and monitoring drive cost.","Autoscale and pooled density materially affect cost; include peak concurrency and idle windows.","Profile and application delivery services can rival host cost."],choices:[{name:"Azure Virtual Desktop",when:"Managed Windows desktop/application delivery."},{name:"Windows 365",when:"Assigned Cloud PCs with simpler management."},{name:"App Service/RemoteApp",when:"Only a web application needs delivery."}],hook:["AVD uses host pools, session hosts, application groups and workspaces.","Exam clue: pooled/personal Windows desktops and RemoteApp delivery point to AVD."]},
  "Windows Server":{summary:"Windows Server workloads hosted on Azure compute with operating-system compatibility, hybrid management and migration options.",concepts:["The Windows Server VM boundary includes OS patching, roles/features, domain membership, licensing and application compatibility.","Azure Arc, Update Manager, Backup and Site Recovery extend management but do not remove workload ownership.","Identity, storage, clustering and network dependencies determine migration and resilience."],fit:["Use it for Windows applications, Active Directory-integrated workloads and migrations that require server compatibility.","Modernize the surrounding platform while keeping the server boundary where application constraints require it.","Choose App Service, Azure SQL or containers when the workload can leave OS-level management."],arch1:["Hybrid Windows application","A Windows Server application runs in Azure while reaching controlled identity and data dependencies through private hybrid connectivity.","Azure Windows Server hybrid pattern","Users","Private ingress → Windows Server VMs","AD / storage / database / Arc"],arch2:["Managed migration and recovery","Servers are assessed, replicated and recovered with patch, backup and monitoring policy applied after landing.","Azure Windows Server migration pattern","Datacenter","Azure Migrate → Azure VMs","Recovery / update / identity / evidence"],security:["Harden Windows images, use Entra/AD controls, JIT administration, Defender and restricted management ports.","Separate domain, server admin, application and backup permissions.","Protect system state, credentials, backups and logs as sensitive infrastructure data."],optimization:["Right-size after migration telemetry, consolidate suitable workloads and use automation for patching and backup.","Use hybrid benefit/licensing options where eligible and avoid oversized always-on servers.","Tune storage and network paths for application dependencies, not only VM CPU."],watch:["A migrated server may preserve technical compatibility while retaining avoidable operational debt.","Domain, DNS, licensing and legacy protocol dependencies often surface after cutover.","Backup and patch compliance need verification, not just policy assignment."],cost:["VM compute, Windows licensing, disks, networking, backup, monitoring, Arc and DR capacity contribute.","Licensing and idle server capacity can dominate the bill.","Compare rehost TCO with application modernization."],choices:[{name:"Windows Server on Azure VM",when:"Windows OS and application compatibility."},{name:"App Service",when:"Web application can use managed runtime."},{name:"Azure VMware Solution",when:"VMware estate continuity is primary."}],hook:["Windows Server on Azure preserves OS/application compatibility but keeps OS operations.","Exam clue: AD, Windows roles, legacy apps and server migration point here."]},
  "Azure Dedicated Host":{summary:"A physical Azure server dedicated to one customer’s VM workloads for isolation, compliance and host-level placement control.",concepts:["A dedicated host is the physical capacity boundary; VMs still have their own size, disks, network and guest OS lifecycle.","Host groups, fault domains and placement determine resilience and maintenance behavior.","Dedicated tenancy addresses placement/isolation requirements, not application high availability by itself."],fit:["Use it when compliance, licensing, workload isolation or host-level control requires dedicated physical capacity.","Distribute hosts and VM instances across fault domains and design application redundancy separately.","Choose regular VMs when logical isolation and standard Azure capacity satisfy the requirement."],arch1:["Isolated regulated workload","A host group contains compliant VMs while application tiers span hosts and zones for service resilience.","Azure Dedicated Host regulated workload","Users","Private ingress → dedicated-host VMs","Host group / disks / identity / audit"],arch2:["License-bound VM estate","Licensed software is placed on dedicated hosts with capacity and maintenance tracked at the host boundary.","Azure Dedicated Host licensing pattern","Platform team","Placement policy → dedicated hosts","VMs / host capacity / maintenance / evidence"],security:["Restrict host-group and placement permissions, harden guests and audit administrative access.","Document physical tenancy and licensing evidence; dedicated host does not replace OS hardening.","Use network, disk and identity controls for the workloads on the host."],optimization:["Pack compatible VM sizes without violating failure-domain or licensing requirements.","Monitor host utilization and plan maintenance/capacity because idle dedicated capacity is expensive.","Use reservations or eligible savings mechanisms after demand stabilizes."],watch:["Dedicated Host is an isolation/placement feature, not a managed database or autoscale service.","A single dedicated host remains a failure domain unless the architecture spans hosts.","Capacity planning is customer-visible and can constrain deployment."],cost:["Dedicated host allocation, VMs, disks, networking, licensing, monitoring and backup drive cost.","You pay for host capacity even when VM packing is inefficient.","Compare dedicated tenancy premium against compliance and licensing value."],choices:[{name:"Dedicated Host",when:"Physical isolation or host-bound licensing."},{name:"Virtual Machines",when:"Standard IaaS placement is sufficient."},{name:"Azure VMware Solution",when:"VMware private-cloud compatibility is needed."}],hook:["Dedicated Host is a physical server boundary for your VMs.","Exam clue: physical isolation, compliance or host-based licensing points here."]},
  "Azure VM Image Builder":{summary:"An Azure service for creating repeatable customized VM images from base images, configuration steps and controlled distribution targets.",concepts:["A build template defines source, customizations, validation and distribution; the resulting image is a versioned artifact.","Image creation is separate from VM deployment, patching and application release orchestration.","Build identity, network access, package sources and cleanup determine supply-chain security."],fit:["Use it to standardize golden images for VM Scale Sets, desktops, servers and specialized fleets.","Bake stable dependencies into images and keep environment-specific configuration at deployment time.","Choose cloud-init or configuration management for fast-changing runtime settings."],arch1:["Golden image pipeline","A source image is customized, validated and published to a shared image gallery for controlled VM rollout.","Azure VM Image Builder golden image pipeline","Platform team","Template → Image Builder","Validation / gallery / rollout / audit"],arch2:["Hardened desktop image","Security baselines and applications are installed, tested and distributed to desktop host pools.","Azure VM Image Builder AVD image pattern","Image team","Base Windows image → builder","Apps / policy / gallery / host pool"],security:["Use managed identity, trusted package sources, signed artifacts and restricted build networking.","Scan and validate images before publication; remove build credentials and temporary artifacts.","Control gallery versions and promotion permissions separately from VM deployment."],optimization:["Cache dependencies and build immutable versions; avoid performing expensive package setup at every VM boot.","Use validation tests for startup, patch level and security controls before broad rollout.","Retain only supported image versions and automate deprecation."],watch:["A golden image becomes stale; image pipelines need patch cadence and ownership.","Build success does not prove the image works with every workload or extension.","Image customization can silently add supply-chain or licensing risk."],cost:["Builder compute, temporary disks, image storage/gallery, network, scanning and downstream VM capacity contribute.","Frequent full builds and retained image versions add storage and build cost.","Balance image bake time against boot-time configuration complexity."],choices:[{name:"VM Image Builder",when:"Repeatable customized golden images."},{name:"Azure Compute Gallery",when:"Versioned image distribution is the main need."},{name:"Cloud-init/configuration management",when:"Runtime configuration changes frequently."}],hook:["Image Builder creates repeatable VM image artifacts; it does not deploy the whole application alone.","Exam clue: source image, customizations, validation and gallery distribution point here."]},
  "Azure Kubernetes Service (AKS)":{summary:"A managed Kubernetes service for deploying containerized applications with Azure-managed control-plane options and customer-managed node/runtime choices.",concepts:["Kubernetes objects, namespaces, controllers, services, ingress and storage define the application plane; Azure networking, identity and policy integrate around it.","The AKS control plane and node pools have different lifecycle, scaling and responsibility boundaries.","Workload identity, image supply chain, observability and upgrade strategy are first-class production concerns."],fit:["Use AKS for complex container platforms needing Kubernetes APIs, operators, portability or fine-grained scheduling.","Use namespaces, managed identity, policy and GitOps to separate teams and promotion paths.","Choose Container Apps for simpler application-centric container hosting or Container Instances for one-off execution."],arch1:["Production AKS platform","Ingress routes to namespaces and deployments, while managed identity, registry, storage and monitoring support the cluster.","Azure Kubernetes Service production baseline","Users","Front Door / ingress → AKS services","Node pools / ACR / identity / monitor"],arch2:["Event-driven worker cluster","Events trigger autoscaled Kubernetes workers that read durable queues and write checkpointed results.","AKS event-driven workload pattern","Event source","Event Hubs → KEDA-scaled pods","Queue / state / policy / telemetry"],security:["Use Entra-integrated RBAC, workload identity, network policy, private clusters and Azure Policy for Kubernetes.","Scan/sign images in ACR and enforce admission, least privilege and non-root execution.","Separate cluster admin, namespace and workload permissions; protect secrets with Key Vault integration."],optimization:["Right-size node pools, use autoscaling and select VM families from actual pod CPU/memory and I/O.","Tune requests/limits, disruption budgets, ingress and storage rather than only adding nodes.","Use spot node pools for tolerant workloads and isolate system/user pools."],watch:["Kubernetes health can be green while application dependencies, certificates or business workflows fail.","Upgrades, add-ons, CRDs and storage compatibility require a tested cadence.","Cluster flexibility brings operational complexity; do not choose AKS solely because containers are involved."],cost:["Node pools, disks, load balancers, registry, networking, monitoring, security and connected data services drive cost.","Control-plane economics do not remove node idle capacity or egress charges.","Estimate cost per workload and cluster overhead separately."],choices:[{name:"AKS",when:"Kubernetes platform control and complex scheduling."},{name:"Container Apps",when:"Managed app-centric containers and revisions."},{name:"Container Instances",when:"Simple isolated container task."}],hook:["AKS manages the Kubernetes control plane but leaves substantial node and workload operations.","Exam clue: namespaces, deployments, ingress, pods and Kubernetes APIs point to AKS."]},
  "Azure Functions":{summary:"A serverless compute service for event-driven functions with managed triggers, bindings, scaling and multiple hosting plans.",concepts:["A function is a code unit activated by a trigger; bindings simplify integration but do not replace authorization or transaction design.","Consumption, Flex Consumption, Premium and Dedicated plans have different cold-start, networking, scaling and billing behavior.","Durable Functions add orchestration/state patterns but still require idempotent activities and externalized business state."],fit:["Use Functions for event handlers, APIs, scheduled automation and short background tasks.","Use queues, retries and idempotency for reliable integration; keep long CPU work in Batch, Container Apps or VMs.","Choose Logic Apps for connector-first business workflows and App Service for continuously hosted web applications."],arch1:["Event-driven order processing","An event triggers validation, a queue absorbs bursts and a function writes a result with retry and telemetry.","Azure Functions event-driven architecture","Event source","Event Grid / Service Bus → Functions","Data / identity / retry / monitor"],arch2:["Durable approval workflow","A durable orchestrator checkpoints activities, waits for human input and resumes without holding a server thread.","Azure Durable Functions orchestration pattern","Requester","API → durable orchestrator","Activities / state / approval / audit"],security:["Use managed identity, function authorization, private endpoints and least-privilege bindings.","Validate trigger payloads, protect host keys and separate deployment identity from runtime identity.","Redact inputs and outputs in logs; event payloads often contain business data."],optimization:["Choose hosting plan from latency, execution duration, concurrency, VNet and scale requirements.","Keep functions small and idempotent, reuse connections and move large payloads through storage references.","Tune queue batch size, retry policy and cold-start behavior with real telemetry."],watch:["At-least-once delivery and retries can duplicate work; design idempotency explicitly.","Execution limits, concurrency and downstream throttling can create hidden backpressure.","Durable orchestration state is not a substitute for a business system of record."],cost:["Executions, duration, memory, plan instances, storage, networking, monitoring and downstream services contribute.","High-frequency timers, retries and chatty bindings can dominate apparently small functions.","Include cold-start mitigation and premium baseline capacity when required."],choices:[{name:"Azure Functions",when:"Event-driven serverless code."},{name:"Logic Apps",when:"Connector-rich business workflow."},{name:"Container Apps",when:"Longer-running containerized worker/API."}],hook:["Functions are trigger-driven code units with plan-specific scaling and billing.","Exam clue: event trigger, bindings and short stateless execution point to Functions."]},
  "Azure Container Instances":{summary:"A fast Azure service for running one or more containers without managing a full orchestrator or VM fleet.",concepts:["Container groups define a shared lifecycle, network namespace and scheduling unit for tightly coupled containers.","ACI is suited to simple execution and burst tasks; it does not provide the full scheduling, rollout and service-discovery model of Kubernetes.","Images, secrets, persistent mounts, restart policy and network exposure need explicit configuration."],fit:["Use ACI for isolated jobs, build agents, quick APIs, test environments and burst execution.","Use a queue or workflow service to submit tasks and store outputs outside the container group.","Choose Container Apps for managed revisions/ingress or AKS for Kubernetes platform requirements."],arch1:["Burst image processing","A queue starts container groups for independent files; results are written to durable storage and groups exit.","Azure Container Instances burst job pattern","Queue","Queue → ACI container group","Blob output / identity / retry / monitor"],arch2:["Sidecar utility group","An API and helper container share a group network namespace for a bounded task with mounted configuration.","Azure Container Instances container group pattern","Client","Private endpoint → ACI group","Main container / sidecar / secret / logs"],security:["Use private networking, managed identity, trusted images and non-root containers where supported.","Keep secrets out of images and define registry pull permissions narrowly.","Restrict public IP exposure and log container access and lifecycle events."],optimization:["Use ACI for short-lived or burst workloads where orchestration overhead would dominate.","Choose image size and startup path carefully; pull time can exceed execution time.","Use container groups only for tightly coupled sidecars, not unrelated services."],watch:["ACI restart and scheduling behavior is not a full deployment controller or Kubernetes service.","No durable state should depend on the container filesystem.","A group’s shared lifecycle can couple failure and scaling of its containers."],cost:["Container CPU/memory duration, image pulls, storage, networking, logs and connected queues contribute.","Short jobs may be dominated by image startup and transfer overhead.","Compare per-task cost with Container Apps jobs or Batch."],choices:[{name:"Container Instances",when:"Simple isolated container execution."},{name:"Container Apps",when:"Managed app ingress, revisions and scale-to-zero."},{name:"AKS",when:"Kubernetes orchestration."}],hook:["ACI runs container groups without managing a cluster; it is not a Kubernetes replacement.","Exam clue: quick isolated container task or burst execution points to ACI."]},
  "Azure Container Apps":{summary:"A managed serverless container platform for APIs, jobs and microservices with revisions, ingress, event-driven scaling and scale-to-zero options.",concepts:["An environment provides shared networking and observability while apps define revisions, ingress, secrets, scale rules and containers.","Revisions and traffic weights support controlled rollout; jobs and applications have different execution models.","Dapr, managed identity and KEDA-style scaling extend the platform but do not remove application correctness concerns."],fit:["Use Container Apps for containerized APIs, workers and microservices when Kubernetes control is unnecessary.","Use revisions and traffic splitting for progressive delivery, and externalize state to managed services.","Choose ACI for simple one-off execution or AKS for cluster-level Kubernetes extensibility."],arch1:["Revision-based microservices","Ingress routes traffic to a revision, services communicate through managed identity and a queue drives worker scale.","Azure Container Apps microservices architecture","Users","Front Door → Container Apps ingress","Revisions / queue / identity / monitor"],arch2:["Event-driven job processing","A scheduled or event-triggered Container Apps job processes work and writes checkpointed results without an always-on API.","Azure Container Apps jobs pattern","Event source","Event Grid → Container Apps job","State / retry / secrets / evidence"],security:["Use managed identity, internal ingress, secret references, registry permissions and environment/network controls.","Separate revision traffic, deployment and runtime identities; restrict Dapr/API exposure.","Scan images and protect logs, environment secrets and service-to-service data."],optimization:["Use scale rules, min/max replicas and workload profiles from measured concurrency and latency.","Use revisions for safe rollout and scale-to-zero where startup behavior is acceptable.","Keep service boundaries small and use queues to absorb bursts rather than overprovisioning replicas."],watch:["Scale-to-zero and event lag can surprise latency-sensitive users.","Revision traffic can split requests across incompatible schemas if migrations are not backward compatible.","Container Apps hides cluster operations but does not guarantee downstream capacity or idempotency."],cost:["vCPU/memory consumption, replicas, jobs, environment resources, networking, registry, logs and dependencies drive cost.","Minimum replicas and always-on components trade latency for baseline cost.","Estimate cost by request, job and idle environment overhead."],choices:[{name:"Container Apps",when:"Managed container APIs, workers and revisions."},{name:"AKS",when:"Kubernetes control and ecosystem are required."},{name:"App Service",when:"Managed web/API runtime without container orchestration needs."}],hook:["Container Apps is app-centric container hosting with revisions, ingress and event scaling.","Exam clue: scale-to-zero, traffic splitting and managed microservices point to Container Apps."]},
  "Nutanix Cloud Clusters":{summary:"A managed Azure landing zone for Nutanix clusters that extends Nutanix HCI operations and workloads into Azure infrastructure.",concepts:["The Nutanix cluster and Azure subscription/networking are distinct management planes with separate identities and support boundaries.","Migration, cluster sizing, licensing, connectivity and DR must be planned as one platform but operated through both systems.","Nutanix portability preserves operational patterns; it does not make workloads cloud-native automatically."],fit:["Use it when Nutanix HCI skills, tooling or application compatibility are important during Azure expansion or migration.","Connect to Azure services selectively while preserving clear ownership of cluster and application operations.","Choose Azure VMware Solution for VMware continuity or native Azure VMs/PaaS for modernization."],arch1:["Nutanix hybrid extension","A Nutanix cluster runs application VMs in Azure while private connectivity reaches shared identity and data services.","Nutanix Cloud Clusters on Azure hybrid pattern","Users","Private ingress → Nutanix cluster","Azure network / identity / storage / monitor"],arch2:["Migration and DR cluster","Replicated workloads land in an Azure Nutanix cluster and a tested runbook validates application dependencies.","Nutanix Cloud Clusters disaster recovery","Primary site","Replication → Azure Nutanix cluster","Recovery / DNS / policy / evidence"],security:["Separate Nutanix and Azure administrative roles, use private connectivity and harden cluster management endpoints.","Protect replication, backup and cluster credentials; enforce least privilege in both planes.","Audit workload movement and data copies across the hybrid boundary."],optimization:["Size clusters from VM CPU, memory, storage and failure-domain needs; avoid importing idle capacity blindly.","Right-size workloads after migration and use native Azure services for new adjacent capabilities.","Test network latency and storage performance before committing application placement."],watch:["Two control planes mean two upgrade, support and incident paths.","Cluster-level capacity is not the same as elastic serverless scale.","A VM migration can succeed while identity, DNS or application dependencies remain broken."],cost:["Azure infrastructure, Nutanix licensing, cluster capacity, storage, networking, backup, DR and monitoring drive cost.","Idle HCI capacity and duplicated recovery environments are material costs.","Include platform operations and licensing in TCO."],choices:[{name:"Nutanix Cloud Clusters",when:"Nutanix HCI continuity in Azure."},{name:"Azure VMware Solution",when:"VMware estate continuity."},{name:"Azure VMs/PaaS",when:"Native modernization is preferred."}],hook:["Nutanix Cloud Clusters preserve Nutanix operations on Azure infrastructure.","Exam clue: HCI cluster portability, Nutanix tooling and hybrid expansion point here."]},
  "Azure Container Registry":{summary:"A managed private registry for storing, scanning, replicating and distributing container images and related OCI artifacts.",concepts:["Repositories, tags, manifests, digests, tasks and geo-replication represent different artifact and distribution concerns.","A digest identifies immutable content; tags are movable pointers and should not be the only deployment reference.","Registry identity, network access, retention and provenance control the software supply chain."],fit:["Use ACR as the trusted image source for AKS, Container Apps, ACI and build pipelines.","Use build tasks or external CI to create signed, scanned images and promote them across environments.","Choose a public registry only when the distribution and trust model genuinely allows it."],arch1:["Secure image promotion","CI builds an image, scans/signs it, pushes by digest and deploys the approved artifact to AKS or Container Apps.","Azure Container Registry supply-chain pattern","Developer","CI → ACR repository","Scan/sign / promotion / runtime pull / audit"],arch2:["Geo-replicated delivery","A registry replicates approved images near regional clusters while deployment policies verify digest and provenance.","Azure Container Registry geo-replication","Build system","ACR → regional runtimes","Replication / policy / cache / monitor"],security:["Use managed identity or federated CI credentials, private endpoints, repository scope and disable broad admin access.","Scan images, sign provenance and enforce admission/deployment policies by digest.","Control retention and deletion because image layers can contain secrets or vulnerable packages."],optimization:["Use layer caching, slim base images and regional replication to reduce build and pull latency.","Promote immutable digests and prune unreferenced layers with a tested retention policy.","Separate build, staging and production repositories or permissions where governance requires."],watch:["A clean tag is not immutable; deployments should record the digest.","Deleting a tag may not delete layers or running images immediately.","Registry availability, network reachability and pull throttling affect startup."],cost:["Registry storage, image operations, builds, scanning, replication, networking and runtime pulls contribute.","Large duplicate layers and excessive retention increase storage and transfer cost.","Optimize image size and regional placement against delivery needs."],choices:[{name:"Azure Container Registry",when:"Private Azure-integrated OCI registry and supply chain."},{name:"Docker Hub",when:"Public/community distribution is the requirement."},{name:"GitHub Container Registry",when:"GitHub-native package workflow is primary."}],hook:["ACR is the private artifact and image supply-chain boundary; runtimes consume its artifacts.","Exam clue: private images, managed identity pulls, scanning and geo-replication point to ACR."]},
  "Azure Container Storage":{summary:"A container-focused storage service for provisioning and managing persistent volumes for stateful container workloads.",concepts:["Persistent volume lifecycle, storage class, access mode and performance tier determine how containers safely use durable data.","The storage plane is separate from the container scheduler; pods/apps can restart while volumes preserve state.","Data replication, backup, encryption and failure-domain behavior must match the database or stateful application."],fit:["Use it for stateful container workloads that need managed persistent volumes and predictable storage integration.","Choose volume type and access mode from application I/O, sharing and recovery requirements.","Use object storage for blobs and AKS/managed database services when they better match the data model."],arch1:["Stateful container database","A containerized database mounts a persistent volume, uses managed identity and sends backups to durable object storage.","Azure Container Storage stateful workload","Application","AKS/containers → persistent volume","Storage class / backup / identity / monitor"],arch2:["High-throughput shared data","Multiple workers mount suitable volumes for a shared processing path while source-of-truth data remains governed.","Azure Container Storage shared volume pattern","Workers","Container workloads → shared storage","I/O tier / access mode / recovery / policy"],security:["Use private networking, encryption, managed identity and least-privilege volume/storage permissions.","Restrict snapshots, backups and administrative storage operations; volumes may contain database secrets.","Test deletion protection, restore and tenant isolation before production."],optimization:["Select performance tier and access mode from measured IOPS, latency and concurrency.","Keep hot state on volumes and use object/archive tiers for backups or cold data.","Avoid overprovisioned capacity and monitor queue depth, filesystem and node I/O."],watch:["Persistent storage does not automatically provide application consistency or backup correctness.","Volume attach/mount behavior can constrain scheduling and failover.","A shared volume can become a contention point or data-corruption risk without application coordination."],cost:["Provisioned capacity, performance tier, snapshots, backups, replication, networking and container compute contribute.","Overprovisioned IOPS and retained snapshots are common cost leaks.","Model recovery copies and peak capacity, not only baseline storage."],choices:[{name:"Azure Container Storage",when:"Persistent volumes for container workloads."},{name:"Azure Managed Disks",when:"VM/AKS disk volumes with direct control."},{name:"Azure Blob Storage",when:"Object data and unstructured files."}],hook:["Container Storage supplies persistent volume behavior; the scheduler and application still own state correctness.","Exam clue: stateful containers, volume classes and persistent I/O point here."]},
  "Azure Linux":{summary:"A Microsoft-maintained Linux distribution and platform foundation optimized for Azure-supported compute and container scenarios.",concepts:["The distribution provides a hardened, supported OS baseline; image lifecycle, packages, kernel behavior and workload configuration remain operational concerns.","Azure Linux can serve VM and container host scenarios with different image and update paths.","OS support, security baseline and application compatibility must be validated against the chosen workload."],fit:["Use Azure Linux for supported Azure VM or container host workloads that benefit from a Microsoft-maintained Linux baseline.","Standardize images and update channels across fleets instead of mixing unmanaged distributions without a reason.","Choose another distribution when vendor packages, kernel modules or application certification require it."],arch1:["Azure Linux VM fleet","A hardened Azure Linux image is distributed to a scale set with managed identity, patching and centralized telemetry.","Azure Linux VM fleet pattern","Platform team","Image → Azure Linux VMSS","Update / identity / storage / monitor"],arch2:["Container host baseline","Azure Linux nodes run container workloads while registry policy, node updates and workload identity remain controlled.","Azure Linux container host pattern","Applications","ACR → Azure Linux nodes","Kubernetes/containers / policy / logs / recovery"],security:["Use signed/hardened images, secure boot where supported, managed identity and restricted administration.","Apply update and vulnerability policies to the OS and container host separately from applications.","Keep package repositories and extensions trusted and auditable."],optimization:["Use a minimal image footprint, standardized image versions and automated rollouts to reduce boot and drift.","Benchmark kernel, filesystem and network behavior for the actual workload.","Separate system and workload capacity and monitor patch/restart impact."],watch:["OS support does not guarantee compatibility with every kernel module or vendor agent.","Image version drift can create fleet inconsistency.","A secure base image still needs application and container hardening."],cost:["VM/container compute, disks, image storage, networking, monitoring and update operations contribute.","Minimal images reduce transfer/startup overhead but do not remove runtime capacity costs.","Include testing and rollout infrastructure in fleet economics."],choices:[{name:"Azure Linux",when:"Microsoft-maintained Linux baseline for Azure workloads."},{name:"Ubuntu/RHEL/SUSE",when:"Workload certification or vendor ecosystem requires it."},{name:"Windows Server",when:"Windows application compatibility is required."}],hook:["Azure Linux is the supported OS foundation; it is not a higher-level container orchestrator.","Exam clue: Microsoft-maintained Linux image and Azure host baseline point here."]},
  "Azure Red Hat OpenShift":{summary:"A managed Red Hat OpenShift service on Azure with supported Kubernetes-compatible platform operations and Red Hat ecosystem integration.",concepts:["OpenShift adds its own control, security, operators, image and developer workflows on top of Kubernetes concepts.","Cluster, node pool, project/namespace, route, operator and registry boundaries need separate governance.","Red Hat support and Azure networking/identity integration create a shared operational model."],fit:["Use it when Red Hat OpenShift compatibility, operators, governance or existing skills are strategic.","Use projects, policies, image controls and GitOps to separate teams and delivery environments.","Choose AKS for Azure-native Kubernetes standardization or Container Apps for app-centric simplicity."],arch1:["Enterprise OpenShift platform","Routes expose applications, operators manage platform services and identity/network policies protect projects.","Azure Red Hat OpenShift enterprise architecture","Users","Ingress/routes → OpenShift projects","Operators / registry / identity / monitor"],arch2:["Governed application promotion","Images are scanned and promoted through environments while GitOps reconciles manifests and policy gates releases.","Azure Red Hat OpenShift GitOps pattern","Delivery team","CI → registry → OpenShift","Projects / policy / secrets / telemetry"],security:["Use OpenShift RBAC, network policy, Entra integration, private clusters and restricted cluster-admin access.","Scan/sign images and manage secrets through supported integrations; constrain operators and service accounts.","Coordinate Red Hat and Azure audit, patch and incident responsibilities."],optimization:["Right-size worker pools and requests/limits, tune cluster add-ons and use autoscaling carefully.","Standardize operators and base images; remove unused workloads and oversized nodes.","Use GitOps and progressive rollout to reduce configuration drift."],watch:["OpenShift adds platform behavior beyond vanilla Kubernetes; validate operator and version compatibility.","Cluster upgrades and add-on support require coordinated planning.","Azure resource health does not cover every OpenShift application failure."],cost:["Worker nodes, storage, networking, registry, support/subscription, monitoring and connected services drive cost.","Idle cluster capacity and platform add-ons create baseline spend.","Include Red Hat licensing/support and operations in TCO."],choices:[{name:"Azure Red Hat OpenShift",when:"Managed OpenShift and Red Hat ecosystem."},{name:"AKS",when:"Azure-native Kubernetes platform."},{name:"Container Apps",when:"Managed container applications without cluster operations."}],hook:["ARO is managed OpenShift on Azure, with OpenShift-specific operators and governance.","Exam clue: Red Hat OpenShift compatibility and managed cluster point to ARO."]},
  "Azure Service Fabric":{summary:"A distributed-systems platform for deploying scalable services and actors with stateful replication, placement and lifecycle management.",concepts:["Service Fabric applications contain services or actors with placement, partitioning, replication and upgrade policies.","Reliable state and service communication are platform capabilities, but application idempotency and data modeling remain important.","Clusters, node types, certificates and upgrade domains form the operational boundary."],fit:["Use it for existing Service Fabric applications or distributed workloads that need its stateful service/actor model.","Design partitions, replicas, quorum and upgrade policy around workload state and failure domains.","Choose AKS for Kubernetes portability or Container Apps for simpler stateless microservices."],arch1:["Stateful actor application","Clients reach a stateless gateway, which calls partitioned stateful actors replicated across node types.","Azure Service Fabric stateful services","Clients","Gateway → Service Fabric services","Actors / replicas / storage / monitor"],arch2:["Rolling cluster upgrade","A versioned application package rolls across upgrade domains while health policies gate progression.","Azure Service Fabric rolling upgrade","Release pipeline","Package → Service Fabric cluster","Upgrade domains / health / rollback / audit"],security:["Use certificates/Entra integration, cluster network isolation, least-privilege service identities and protected secrets.","Secure inter-service communication and restrict cluster administrator operations.","Audit upgrades, replica movement and state access."],optimization:["Choose partition count, replica placement and node types from state size, traffic and failure domains.","Tune reliable collections, communication and upgrade health policies with production-like tests.","Use autoscaling and right-sized nodes carefully; stateful replicas need capacity headroom."],watch:["Quorum and replica placement affect availability; adding nodes does not fix poor partitioning.","Stateful services require careful versioning and schema migration.","Platform complexity can outweigh benefits for new simple stateless APIs."],cost:["Cluster node VMs, disks, networking, load balancing, monitoring, backups and operations contribute.","Replica count and headroom increase baseline capacity.","Include engineering and upgrade expertise in service selection."],choices:[{name:"Service Fabric",when:"Existing stateful services/actors and platform continuity."},{name:"AKS",when:"Kubernetes ecosystem and portability."},{name:"Container Apps",when:"Simpler stateless microservices."}],hook:["Service Fabric is a distributed application platform with services, actors, partitions and replicas.","Exam clue: Reliable Services/Actors and replica-aware upgrades point to Service Fabric."]},
  "Azure Kubernetes Fleet Manager":{summary:"A management service for organizing multiple Kubernetes clusters and coordinating policy, workload placement and updates across a fleet.",concepts:["A fleet groups member clusters while workloads, namespaces and node operations still exist in each member cluster.","Placement, update orchestration and topology decisions are fleet concerns; application state and cluster-specific capabilities remain local.","Multi-cluster governance requires consistent identity, policy, version and observability practices."],fit:["Use it when many AKS clusters need coordinated workload placement, upgrades or policy management.","Use fleet membership and placement rules to express regional, environment and capacity intent.","Choose a single AKS cluster when multi-cluster failure isolation or regional distribution is unnecessary."],arch1:["Multi-region AKS fleet","A platform team places workloads across member clusters and routes users to the healthy regional service.","Azure Kubernetes Fleet Manager multi-cluster pattern","Users","Global ingress → fleet member clusters","Placement / policy / identity / monitor"],arch2:["Coordinated cluster update","A fleet update plan rolls Kubernetes versions through canaries, then expands after health and policy checks.","Azure Kubernetes Fleet Manager upgrade pattern","Platform team","Fleet update plan → member clusters","Canary / policy / rollback / evidence"],security:["Use fleet and member-cluster RBAC separately, enforce policy per cluster and protect cross-cluster credentials.","Keep tenant/workload identities scoped; fleet access must not imply namespace access everywhere.","Audit placement, policy and upgrade actions across the fleet."],optimization:["Balance workload placement against data locality, egress, capacity and failure isolation.","Canary updates and standardize cluster add-ons/images to reduce fleet variance.","Use shared observability and policy baselines without forcing identical workloads everywhere."],watch:["Fleet coordination does not erase cluster version, add-on or network differences.","Cross-region routing and state replication remain application responsibilities.","A fleet-wide policy change can have a large blast radius; stage it."],cost:["Member cluster nodes, fleet management, networking, ingress, monitoring, policy and replicated data drive cost.","Multi-cluster redundancy increases baseline spend and operational overhead.","Compare fleet value against a simpler cluster with zones."],choices:[{name:"Kubernetes Fleet Manager",when:"Coordinated multi-cluster AKS management."},{name:"AKS",when:"Single-cluster Kubernetes platform."},{name:"Azure Front Door",when:"Global routing without fleet orchestration."}],hook:["Fleet Manager coordinates clusters; it does not turn multiple clusters into one control plane.","Exam clue: multi-cluster placement, policy and upgrade orchestration point here."]}
};

const computeContainerDetails:Record<string,Detail> = Object.fromEntries(Object.entries(computeContainerProfiles).map(([name,p])=>[name,{category:name.includes("Container")||name.includes("Kubernetes")||name.includes("OpenShift")||name.includes("Service Fabric")||name.includes("Fleet")?"Containers":"Compute",summary:p.summary,concepts:p.concepts,fit:p.fit,architectures:[A(p.arch1[0],p.arch1[1],p.arch1[2],L("Workload",N(name,p.arch1[3],"compute")),L("Flow",N(p.arch1[4],"Azure implementation path","app")),L("Platform",N(p.arch1[5].split(" / ")[0],"Native service boundary","compute")),L("Dependencies",N("Azure Storage","Durable state or artifacts","storage"),N("Microsoft Entra ID","Identity","security")),L("Operations",N("Azure Monitor","Health and diagnostics","monitor"))),A(p.arch2[0],p.arch2[1],p.arch2[2],L("Trigger",N(p.arch2[3],"Workload intent","user")),L("Implementation",N(p.arch2[4],"Service-specific path","compute")),L("Controls",N(p.arch2[5].split(" / ")[0],"Boundary and policy","security")),L("Data",N("Azure Storage","Durable data","storage"),N("Azure Monitor","Evidence","monitor")),L("Outcome",N("Application result","Validated output","app")))],security:p.security,optimization:p.optimization,watch:p.watch,cost:p.cost,choices:p.choices,hook:p.hook}]));
Object.assign(D,computeContainerDetails);

// Developer and DevOps pages use a compact, service-specific profile catalog.
// The shared factory keeps the AWS-style page structure consistent while every
// service supplies its own Azure boundary, workflow, controls, cost drivers,
// alternatives and exam cues.
type DeliveryProfile={summary:string;focus:string;flow:string;fit:string;boundary:string;risk:string;cost:string;alternative:string;hook:string};
const deliveryProfiles:Record<string,DeliveryProfile>={
  "App Configuration":{summary:"A managed key-value configuration store for centralizing application settings, feature flags and environment-specific values.",focus:"key-values, labels and feature flags",flow:"application startup and refresh reads a labeled configuration snapshot",fit:"Use it to externalize settings and release flags without redeploying application binaries.",boundary:"configuration store",risk:"stale refreshes or an overly broad read identity can expose the wrong environment",cost:"store operations, replicas, network access and connected application refresh traffic",alternative:"Key Vault when the value is a secret rather than ordinary configuration",hook:"labels separate environments and feature flags control release exposure; App Configuration is not a secret vault."},
  "Azure DevOps":{summary:"An integrated Azure service suite for planning work, hosting code, building, testing and releasing software.",focus:"Boards, Repos, Pipelines, Test Plans and Artifacts",flow:"work item moves from backlog to pull request, pipeline, test evidence and release",fit:"Use it when one integrated Azure DevOps organization should connect planning, source, CI/CD and quality evidence.",boundary:"organization, project and team boundaries",risk:"project permissions, service connections and branch policies can silently widen release authority",cost:"parallel jobs, hosted agents, storage, test execution, artifacts and user licensing",alternative:"GitHub plus Azure deployment services when GitHub is the primary collaboration boundary",hook:"Azure DevOps spans plan, code, build, test and deploy; its components are complementary, not interchangeable."},
  "Azure DevTest Labs":{summary:"A managed lab service for creating controlled development and test environments with quotas, policies and reusable images.",focus:"lab VMs, formulas, quotas and auto-shutdown",flow:"developer requests a permitted VM from an approved image and lab policy",fit:"Use it to give teams self-service test VMs while controlling spend, images, schedules and access.",boundary:"lab policy and VM lifecycle boundary",risk:"a lab policy is not a production security boundary and unmanaged VMs can retain sensitive data",cost:"VM compute, disks, images, networking and retained test environments",alternative:"Microsoft Dev Box for standardized developer workstations",hook:"DevTest Labs optimizes governed test VM self-service; it is not a production VM orchestrator."},
  "Azure Pipelines":{summary:"A CI/CD service for defining repeatable build, test and deployment automation with Microsoft-hosted or self-hosted agents.",focus:"YAML pipelines, stages, agents, approvals and artifacts",flow:"commit triggers a build, tests produce evidence, then gated stages deploy an artifact",fit:"Use it for multi-stage delivery with approvals, environments, service connections and reusable pipeline templates.",boundary:"pipeline, agent pool and environment boundary",risk:"pipeline YAML is code with production authority; protect branches, variables, approvals and service connections",cost:"parallel jobs, agent minutes, self-hosted infrastructure, artifacts and test workloads",alternative:"GitHub Actions when the repository and workflow boundary are GitHub-native",hook:"Pipelines build and release artifacts; environments and approvals protect deployment, while agents execute tasks."},
  "SDKs":{summary:"Azure client libraries and developer kits that expose typed APIs, authentication helpers and service-specific programming models.",focus:"language packages, client abstractions and Azure Identity",flow:"application obtains a token through a credential chain and calls a typed Azure client",fit:"Use SDKs when application code needs maintainable service integration instead of hand-built REST requests.",boundary:"application dependency and API-version boundary",risk:"credential-chain behavior, package upgrades and accidental broad permissions affect runtime security",cost:"API calls, dependency maintenance, telemetry and the Azure resources called by the SDK",alternative:"Azure CLI or REST when automation is outside an application runtime",hook:"An SDK is a client library, not a hosted Azure service; identity and data-plane permissions still apply."},
  "Visual Studio":{summary:"Microsoft’s full-featured IDE for .NET and Azure application development, debugging, profiling and deployment.",focus:"solution management, debugger, Azure tooling and publish profiles",flow:"developer debugs locally, provisions or selects Azure resources, then publishes a controlled artifact",fit:"Use it for rich .NET debugging, profiling, Azure integrations and enterprise solution development.",boundary:"developer workstation and project/solution boundary",risk:"local publish profiles and cached credentials can become an unmanaged production path",cost:"IDE licensing, developer workstations, build agents and connected Azure resources",alternative:"Visual Studio Code for a lighter, extensible editor workflow",hook:"Visual Studio is the IDE and developer toolchain; the deployed Azure runtime remains a separate service boundary."},
  "Visual Studio Code":{summary:"A lightweight extensible editor with Azure extensions, terminals, debugging and language tooling for cloud development.",focus:"extensions, dev containers, terminals and source control",flow:"developer edits in a reproducible workspace, runs local tests and invokes a controlled deployment task",fit:"Use it for polyglot cloud projects, remote development, containers and fast repository-based workflows.",boundary:"editor workspace and extension boundary",risk:"extensions execute code and may read credentials; enforce workspace trust and least privilege",cost:"editor extensions, remote compute, build agents and the Azure workloads they invoke",alternative:"Visual Studio when deep .NET profiling and full IDE workflow are required",hook:"VS Code supplies an extensible client workflow; extensions do not replace pipeline governance."},
  "Azure App Testing":{summary:"Azure’s managed testing capabilities for load and browser-based end-to-end validation of application behavior.",focus:"load tests, browser scenarios, test engines and result telemetry",flow:"test definition runs against a deployed target and publishes latency, failures and traces",fit:"Use it to validate scale behavior and realistic browser journeys before release.",boundary:"test workspace and target-environment boundary",risk:"tests can generate production-like load and may handle credentials or customer-shaped data",cost:"test engine time, virtual users, browser execution, storage and monitoring",alternative:"Azure Test Plans for manual/exploratory test management",hook:"App Testing measures deployed behavior at scale; it is not a CI source repository or a production load balancer."},
  "Microsoft Dev Box":{summary:"A managed developer workstation service that provides project-ready, policy-controlled cloud development machines.",focus:"dev box pools, catalogs, images, projects and user assignment",flow:"platform team publishes an image, project policy assigns a pool and a developer connects to a dev box",fit:"Use it for consistent, secure developer environments without shipping high-powered laptops.",boundary:"project, pool, image and user assignment boundary",risk:"persistent developer machines can retain source, tokens and secrets; apply lifecycle and access policy",cost:"compute uptime, storage, image management, networking and user entitlement",alternative:"DevTest Labs for ad hoc test VMs and lighter lab governance",hook:"Dev Box is a managed developer workstation, not a CI agent pool or production application host."},
  "Azure Deployment Environments":{summary:"A managed self-service platform for provisioning standardized application environments from governed templates and catalogs.",focus:"catalogs, environment definitions, projects and developer self-service",flow:"developer requests an environment, a template deploys it, and project policy controls its lifecycle",fit:"Use it when teams need repeatable cloud environments with platform guardrails and delegated provisioning.",boundary:"project, catalog and environment lifecycle boundary",risk:"template changes and deployment identities can affect many teams; review permissions and teardown behavior",cost:"deployed infrastructure, template pipeline runs, storage and retained environments",alternative:"Azure DevTest Labs for VM-centric test labs",hook:"Deployment Environments governs environment provisioning from templates; it is not an IaC language itself."},
  "Microsoft Playwright Testing":{summary:"A fully managed cloud browser testing service for running Playwright suites across browser and operating-system combinations.",focus:"cloud-hosted browsers, parallel workers, traces and debugging",flow:"Playwright test suite connects to a workspace and executes parallel browser sessions against the target",fit:"Use it for scalable end-to-end browser coverage without managing browser infrastructure.",boundary:"workspace, test run and target application boundary",risk:"test identities, traces and screenshots can contain customer data or credentials",cost:"browser execution, parallelism, storage of traces and test-run telemetry",alternative:"Azure App Testing load tests when the primary question is throughput rather than user journeys",hook:"Playwright Testing provides managed browsers and parallel execution; your test code and target app remain separate."},
  "Artifact Signing":{summary:"A managed signing capability for attaching verifiable signatures to software artifacts and establishing release provenance.",focus:"signing accounts, identities, certificates and verification",flow:"a trusted pipeline submits an artifact, signing policy authorizes it and consumers verify provenance",fit:"Use it to make binaries, packages or containers verifiable across the software supply chain.",boundary:"signing identity and release-provenance boundary",risk:"signing authority is equivalent to release authority; isolate it from ordinary build permissions",cost:"signing operations, certificate/key protection, pipeline runs and verification tooling",alternative:"ACR content trust or repository-native signing when the artifact remains inside that ecosystem",hook:"Signing proves provenance and integrity; it does not scan the artifact or decide whether the code is safe."},
  "Azure Artifacts":{summary:"A package management service in Azure DevOps for hosting and consuming feeds of NuGet, npm, Maven, Python and other packages.",focus:"feeds, views, upstream sources and package retention",flow:"pipeline publishes an immutable package, consumers restore through an authorized feed and promote a view",fit:"Use it to share private packages and control dependency promotion across teams and environments.",boundary:"organization, feed and view boundary",risk:"upstream packages and feed permissions can introduce supply-chain risk",cost:"package storage, retention, upstream caching and pipeline transfer",alternative:"GitHub Packages when GitHub is the primary package boundary",hook:"Artifacts manages packages and feeds; it is not the source repository and a feed view is not a security scan."},
  "Azure Boards":{summary:"A work-tracking service for backlogs, agile planning, work items, queries, dashboards and delivery traceability.",focus:"work items, backlogs, iterations, area paths and boards",flow:"requirement becomes a work item, moves through state transitions and links to code and release evidence",fit:"Use it to plan and trace product work across teams with configurable process templates.",boundary:"organization, project, team and area/iteration boundary",risk:"permissions and inherited process rules affect who can change scope or close work",cost:"user access, extensions, dashboards and connected delivery tooling",alternative:"GitHub Issues or Jira when those are the established planning system",hook:"Boards tracks intent and delivery state; it does not build code or deploy infrastructure."},
  "Azure Monitor":{summary:"Azure’s unified observability platform for metrics, logs, traces, alerts, workbooks and application performance signals.",focus:"metrics, Log Analytics, Application Insights, alerts and workbooks",flow:"resource and application telemetry is collected, queried, correlated and routed to action",fit:"Use it to detect health, investigate incidents and connect service signals to operational response.",boundary:"workspace, data-collection rule and alert-action boundary",risk:"telemetry can contain secrets or personal data and broad workspace access exposes many workloads",cost:"ingestion, retention, queries, exports, alerts and Application Insights telemetry",alternative:"Azure Managed Grafana for dashboarding over telemetry when visualization is the main need",hook:"Monitor collects and analyzes signals; an alert is a decision/action path, not the metric itself."},
  "Azure Repos":{summary:"Git repositories and pull-request workflows in Azure DevOps with branch policies, reviewers and code traceability.",focus:"repositories, branches, pull requests and branch policies",flow:"commit enters a protected branch through review, validation and merge policy",fit:"Use it when Azure DevOps provides the source-control and work-item integration boundary.",boundary:"organization, project and repository boundary",risk:"branch policies, token scopes and repository permissions protect the path to production",cost:"repository storage, users, pipelines and retention of history/artifacts",alternative:"GitHub when open collaboration or GitHub-native automation is preferred",hook:"Repos stores and reviews source; Pipelines executes delivery after code passes repository controls."},
  "Azure Test Plans":{summary:"A test-management service for manual, exploratory and automated test planning with suites, cases, configurations and evidence.",focus:"test plans, suites, cases, configurations and exploratory sessions",flow:"requirement links to a test case, execution records evidence and defects feed back to work tracking",fit:"Use it for structured release quality evidence where manual and exploratory coverage matters.",boundary:"project, plan, suite and test-result boundary",risk:"test data and attachments may contain customer information; control access and retention",cost:"user access, test execution, storage and connected pipeline runs",alternative:"Microsoft Playwright Testing for managed browser automation at scale",hook:"Test Plans manages test intent and evidence; Pipelines or Playwright performs automated execution."},
  "DevOps tool integrations":{summary:"Integration patterns and extensions that connect Azure DevOps delivery signals to repositories, services, chat, ITSM and deployment targets.",focus:"service hooks, extensions, webhooks and connected delivery systems",flow:"work or pipeline event is filtered, signed and delivered to an external tool for action or visibility",fit:"Use it when delivery must coordinate with incident, security, collaboration or release-management systems.",boundary:"event subscription, extension and external-system trust boundary",risk:"webhook secrets, replay, duplicate events and overly broad subscriptions can create automation paths",cost:"connected SaaS plans, pipeline runs, event volume, agents and monitoring",alternative:"Native Azure DevOps features when an external system adds no required capability",hook:"Integrations move signals between tools; they do not become a replacement for the source system’s permissions."},
  "Azure Managed Grafana":{summary:"A managed Grafana workspace for querying and visualizing Azure Monitor and other operational data sources.",focus:"dashboards, data sources, folders, teams and alert views",flow:"operators query governed telemetry and use dashboards to investigate or communicate service health",fit:"Use it for shared operational visualization when teams need Grafana dashboards without managing servers.",boundary:"workspace, data-source and team/folder boundary",risk:"dashboard access can expose sensitive telemetry and data-source credentials",cost:"workspace instance, user access, data queries and underlying telemetry retention",alternative:"Azure Monitor Workbooks for Azure-native investigation and runbook context",hook:"Managed Grafana visualizes data; it does not collect telemetry or replace the underlying alerting system."},
  "GitHub Advanced Security for Azure DevOps":{summary:"Security capabilities integrated with Azure DevOps for code and dependency risk detection, including secret and vulnerability analysis.",focus:"dependency scanning, secret protection and code security findings",flow:"pull request or repository scan produces findings that block or inform promotion",fit:"Use it to add developer-facing security checks directly to Azure Repos and Azure Pipelines workflows.",boundary:"repository, branch policy and security finding boundary",risk:"scanners need protected access to source and findings must be triaged without leaking secrets",cost:"licensed contributors, scan execution, storage and remediation workload",alternative:"GitHub Advanced Security when repositories live on GitHub",hook:"Advanced Security finds and protects code risks; it does not replace identity, runtime security or threat response."},
  "Github Enterprise":{summary:"An enterprise GitHub collaboration and software-delivery platform used here as a DevOps branch service for governed repositories and teams.",focus:"enterprise organizations, repositories, policies and Actions",flow:"developer opens a pull request, policy checks run and an approved workflow publishes a release",fit:"Use it when enterprise collaboration, GitHub-native development and centralized repository policy are required.",boundary:"enterprise, organization and repository boundary",risk:"tokens, Actions permissions, runners and outside collaborators need explicit governance",cost:"licensed users, Actions minutes, storage, runners and security features",alternative:"Azure DevOps when integrated Boards/Repos/Pipelines workflows are the primary boundary",hook:"GitHub Enterprise governs GitHub organizations and repositories; it is not the same service as Azure DevOps."},
  "GitHub Advanced Security":{summary:"GitHub’s application-security capabilities for finding vulnerabilities, secrets and unsafe patterns during development.",focus:"code scanning, secret scanning and dependency review",flow:"commit or pull request is analyzed and findings become developer remediation work",fit:"Use it to shift application-security feedback into the repository and review workflow.",boundary:"repository, organization policy and security-alert boundary",risk:"alerts and secret detections are sensitive; protect access and rotate exposed credentials immediately",cost:"licensed contributors, analysis minutes, storage and remediation effort",alternative:"GitHub Advanced Security for Azure DevOps when source is hosted in Azure Repos",hook:"GitHub Advanced Security secures the development workflow; a passing scan does not prove runtime safety."},
  "GitHub Copilot":{summary:"An AI coding assistant for generating, explaining, transforming and navigating code within supported developer workflows.",focus:"code suggestions, chat context, repository policy and review",flow:"developer asks for or accepts a suggestion, then tests and reviews the resulting change",fit:"Use it to accelerate coding and explanation while keeping human review, tests and repository policy authoritative.",boundary:"developer context, organization policy and generated-code boundary",risk:"prompts, repository context and generated code require privacy, IP and review controls",cost:"licensed seats, usage plans, code review time and downstream CI execution",alternative:"Microsoft Foundry or Azure OpenAI for building a custom governed coding assistant",hook:"Copilot assists the developer; it is not an automated approval gate and generated code still needs validation."},
  "Azure SRE Agent":{summary:"An Azure-oriented AI operations agent that assists with investigation, diagnosis and guided remediation of service reliability issues.",focus:"incident context, telemetry reasoning, runbooks and guarded actions",flow:"alert supplies context, the agent investigates evidence, proposes or executes an approved action",fit:"Use it to reduce toil in Azure operations when actions are bounded, auditable and human-governed.",boundary:"incident, tool permission and remediation-action boundary",risk:"agent tool access can change production; require least privilege, approvals, dry runs and audit trails",cost:"agent usage, telemetry queries, model calls, runbook execution and monitored resources",alternative:"Azure Monitor plus automation runbooks when deterministic operations are sufficient",hook:"SRE Agent reasons over operational evidence and actions; it must not receive unrestricted production authority."}
};

const deliveryDetails:Record<string,Detail>=Object.fromEntries(Object.entries(deliveryProfiles).map(([name,p])=>[name,{category:"Developer / DevOps",summary:p.summary,concepts:[`${name} centers on ${p.focus}; keep that boundary explicit in the design.`,`Its implementation flow is ${p.flow}; the platform does not replace application or team ownership outside that boundary.`,`Identity, lifecycle and observability must be designed alongside ${p.focus}, not added after the first deployment.`],fit:[p.fit,`Place ${name} where ${p.boundary} is the control point and connect it to the smallest required Azure resources.`,`Do not use ${name} when the primary requirement is ${p.alternative.toLowerCase()}.`],architectures:[A(`${name} delivery path`,`${p.flow}.`,`${name} Azure reference pattern`,L("Team",N("Developer or operator","Intent and change","user")),L("Control",N(name,p.boundary,"app")),L("Workload",N("Azure application","Build, test or operate","compute")),L("Evidence",N("Azure Monitor","Logs and health","monitor")),L("Identity",N("Microsoft Entra ID","Scoped access","security"))),A(`${name} governed lifecycle`,`${name} is promoted through an explicit control boundary with evidence before the next environment or action.`,`Azure ${name} governance and operations pattern`,L("Input",N(p.focus,"Source event or artifact","data")),L("Decision",N(name,"Policy, review or execution","app")),L("Target",N(p.flow,"Service-specific outcome","compute")),L("Protection",N("Entra ID / policy","Least privilege","security")),L("Operations",N("Azure Monitor","Trace, alert and recovery","monitor")))],security:[`Protect the ${p.boundary} with Entra ID, least-privilege roles, scoped service connections and separate production permissions.`,`Treat ${p.focus} as potentially sensitive and control secrets, logs, artifacts and retention.`,`Audit changes, approvals and automation actions so failures can be traced to an identity and version.`],optimization:[`Optimize ${p.focus} using measured workload volume, concurrency, retention and environment lifecycle rather than a default tier.`,`Automate repeatable setup and cleanup, but keep policy and production promotion explicit.`,`Use Azure Monitor evidence to tune latency, failure rate, idle capacity and developer/operator feedback.`],watch:[p.risk,`${name} can report a successful step while a downstream system, policy or artifact is still stale; validate the end-to-end result.`,`Duplicate permissions, environments or integrations create hidden coupling and cost; keep ownership visible.`],cost:[p.cost,`Include connected compute, storage, networking, telemetry, identities and pipeline or test execution in the total request path.`,`Measure cost per build, environment, test run, package, incident or approved change—not only the service unit price.`],choices:[{name,when:p.fit},{name:p.alternative,when:"Choose this when its boundary is the primary requirement rather than "+name+"."},{name:"Azure Monitor",when:"Choose this for shared operational evidence and health signals around the workload."}],hook:[p.hook,`Exam clue: choose ${name} when the requirement is specifically ${p.focus}.`] }]));
Object.assign(D,deliveryDetails);


type DataIdentityProfile={summary:string;focus:string;flow:string;fit:string;boundary:string;watch:string;alternative:string;cost:string;hook:string};
